<?php
class NotificationService
{
    private $pdo;
    public function __construct($pdo){$this->pdo=$pdo;}
    public function create($userId,$type,$title,$content,$orderNo=null,$targetType=null,$targetId=null,$dedupeKey=null)
    {
        $userId=(int)$userId; if($userId<1) throw new InvalidArgumentException('通知用户无效。');if(!is_string($type)||mb_strlen($type,'UTF-8')>40||($orderNo!==null&&!is_string($orderNo))||($targetType!==null&&!is_string($targetType)))throw new InvalidArgumentException('通知字段长度或格式无效。');
        if(!is_string($type)||!is_string($title)||!is_string($content)||($dedupeKey!==null&&!is_string($dedupeKey)))throw new InvalidArgumentException('通知字段格式无效。');$title=trim($title); $content=trim($content);
        if($title===''||mb_strlen($title,'UTF-8')>200) throw new InvalidArgumentException('通知标题长度无效。');
        if($dedupeKey!==null&&($dedupeKey===''||strlen($dedupeKey)>160||!preg_match('/^[A-Za-z0-9:_-]+$/',$dedupeKey)))throw new InvalidArgumentException('通知去重键无效。');
        if(function_exists('mb_substr')) $content=mb_substr($content,0,1000,'UTF-8'); else $content=substr($content,0,3000);
        $sql='INSERT INTO notifications(user_id,type,title,content,order_no,target_type,target_id,dedupe_key,created_at) VALUES(?,?,?,?,?,?,?,?,?)';
        $dbType=$type;$dbTitle=mb_substr($title,0,200,'UTF-8');$dbOrder=$orderNo!==null?substr($orderNo,0,40):null;$dbTarget=$targetType!==null?substr($targetType,0,40):null;$dbKey=$dedupeKey;$dbTargetId=$targetId!==null?(int)$targetId:null;try { $s=$this->pdo->prepare($sql); $s->execute(array($userId,$dbType,$dbTitle,$content,$dbOrder,$dbTarget,$dbTargetId,$dbKey,date('Y-m-d H:i:s'))); return (int)$this->pdo->lastInsertId(); }
        catch(PDOException $e){ if($dedupeKey!==null && $this->isDuplicate($e)){ $q=$this->pdo->prepare('SELECT id,type,title,content,order_no,target_type,target_id FROM notifications WHERE user_id=? AND dedupe_key=?');$q->execute(array($userId,$dedupeKey));$existing=$q->fetch(PDO::FETCH_ASSOC);if($existing!==false){if((string)$existing['type']!==$dbType||(string)$existing['title']!==$dbTitle||(string)$existing['content']!==$content||(string)$existing['order_no']!==(string)$dbOrder||(string)$existing['target_type']!==(string)$dbTarget||((int)$existing['target_id']!==(int)$dbTargetId))throw new RuntimeException('通知去重键内容冲突。');return (int)$existing['id'];} } throw $e; }
    }
    private function isDuplicate($e){return (int)$e->errorInfo[1]===1062;}
    public function unreadCount($userId){$s=$this->pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL');$s->execute(array((int)$userId));return (int)$s->fetchColumn();}
    public function recent($userId,$limit=5){$limit=max(1,min(20,(int)$limit));$s=$this->pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT '.$limit);$s->execute(array((int)$userId));return $s->fetchAll(PDO::FETCH_ASSOC);}
    public function paginate($userId,$page=1,$perPage=20,$readFilter=null,$type=null){$page=max(1,(int)$page);$perPage=max(1,min(50,(int)$perPage));$where='user_id=?';$args=array((int)$userId);if($readFilter==='unread')$where.=' AND read_at IS NULL';elseif($readFilter==='read')$where.=' AND read_at IS NOT NULL';if($type!==null&&$type!==''){$where.=' AND type=?';$args[]=$type;}$c=$this->pdo->prepare('SELECT COUNT(*) FROM notifications WHERE '.$where);$c->execute($args);$total=(int)$c->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$s=$this->pdo->prepare('SELECT * FROM notifications WHERE '.$where.' ORDER BY created_at DESC,id DESC LIMIT '.$offset.','.$perPage);$s->execute($args);return array('items'=>$s->fetchAll(PDO::FETCH_ASSOC),'total'=>$total,'page'=>$page,'pages'=>$pages);}
    public function markRead($userId,$id){$s=$this->pdo->prepare('UPDATE notifications SET read_at=? WHERE id=? AND user_id=? AND read_at IS NULL');$s->execute(array(date('Y-m-d H:i:s'),(int)$id,(int)$userId));return $s->rowCount()===1;}
    public function markAllRead($userId){$s=$this->pdo->prepare('UPDATE notifications SET read_at=? WHERE user_id=? AND read_at IS NULL');$s->execute(array(date('Y-m-d H:i:s'),(int)$userId));return $s->rowCount();}
    public function targetPath($row){$type=isset($row['target_type'])?$row['target_type']:'';$id=(int)(isset($row['target_id'])?$row['target_id']:0);if($type===''&&$id===0&&!empty($row['order_no'])){ $s=$this->pdo->prepare('SELECT id FROM orders WHERE order_no=? AND user_id=?');$s->execute(array($row['order_no'],(int)$row['user_id']));if($s->fetchColumn()!==false)return '/orders/'.rawurlencode($row['order_no']); }if($type==='order'&&$id>0){$s=$this->pdo->prepare('SELECT order_no FROM orders WHERE id=? AND user_id=?');$s->execute(array($id,(int)$row['user_id']));$no=$s->fetchColumn();if($no!==false)return '/orders/'.rawurlencode($no);return null;}if($type==='feedback'&&$id>0)return '/feedback/'.$id;if($type==='ticket'&&$id>0)return '/tickets/'.$id;if($type==='announcement'&&$id>0)return '/announcements/'.$id;return null;}
}
